    h += "function renderReorganize(){let assignHtml=\"\";let screens=[[\"signin\",\"1. Sign-In\"],[\"landing\",\"2. Landing\"],[\"floor-scan\",\"3. Floor Scan\"],[\"dev\",\"4. Dev Online Seen\"],[\"preview\",\"5. Invoice Columns\"],[\"ai\",\"6. Kai AI\"],[\"subscribe\",\"7. Packages\"]];screens.forEach(function(s){let sid=s[0];let sname=s[1];let currentIdx=mapping[sid]||0;assignHtml+=\"<div class='bg-white/[0.04] border rounded-xl p-3'><div class='flex justify-between'><div class='font-bold text-[11px]'>\"+sname+\"</div><div class='text-[9px] bg-[#5b7cff] px-2 py-1 rounded-full'>IMG-\"+currentIdx+\"</div></div><div class='mt-2 grid grid-cols-4 gap-1'>\";for(let i=0;i<7;i++){let active=(mapping[sid]===i)?\"bg-[#5b7cff]\":\"bg-white/5\";assignHtml+=\"<button onclick=\\\"setMapping('\"+sid+\"',\"+i+\")\\\" class='border rounded p-1 \"+active+\"'><img src='/img/\"+i+\"' class='w-full h-10 object-cover rounded'></button>\";}assignHtml+=\"</div></div>\";});let el2=document.getElementById(\"assignList\");if(el2){el2.innerHTML=assignHtml;}}\n"
